CREATE TABLE patients (
  id INTEGER NOT NULL PRIMARY KEY AUTO_INCREMENT,
  surname VARCHAR(50) NOT NULL,
  forename VARCHAR(50) NOT NULL,
  addname VARCHAR(50),
  title VARCHAR(30),
  birthday DATE,
  gender INTEGER,
  street VARCHAR(50),
  city VARCHAR(50),
  zip VARCHAR(5),
  tel VARCHAR(20),
  tel_job VARCHAR(20),
  mobile VARCHAR(20),
  fax VARCHAR(20),
  email VARCHAR(50),
  insurance VARCHAR(9),
  vnr VARCHAR(15),
  status VARCHAR(4),
  kvknr VARCHAR(50),
  kvkvalid VARCHAR(10),
  notices VARCHAR(256),
  itype INTEGER REFERENCES ins_type(id),
  pgroup INTEGER REFERENCES patient_groups(id),
  care_facility INTEGER,
  distance INTEGER,
  def_eid INTEGER REFERENCES employees(id),
  def_pid INTEGER REFERENCES physicians(id),
  state INTEGER REFERENCES patient_states(id),
  addpay_freed INTEGER,
  freed_from DATE,
  freed_until DATE
);
CREATE UNIQUE INDEX uiPat1 ON patients(surname,forename,birthday);


