DELIMITER |
CREATE TRIGGER update_receipe_relations AFTER DELETE ON receipes
FOR EACH ROW
BEGIN
  DELETE FROM dates WHERE dates.rid = old.id;
END;
|
DELIMITER ;

DELIMITER |
CREATE TRIGGER update_patient_relations AFTER DELETE ON patients
FOR EACH ROW
BEGIN
  DELETE FROM findings WHERE findings.pid = old.id;
  DELETE FROM dates where dates.pid = old.id;
  DELETE FROM receipes where receipes.pid = old.id;
END;
|
DELIMITER ;
